-- Create cleanup procedure
DROP PROCEDURE IF EXISTS CleanOldHealthReports;
CREATE PROCEDURE CleanOldHealthReports()
BEGIN
    DECLARE retention_days INT DEFAULT 30;
    DECLARE deleted_reports INT DEFAULT 0;
    DECLARE deleted_alerts INT DEFAULT 0;

    -- Get retention period from config
    SELECT CAST(config_value AS UNSIGNED) INTO retention_days 
    FROM config WHERE config_key = 'data_retention_days';

    -- Delete old health reports
    DELETE FROM health_reports 
    WHERE checked_at < DATE_SUB(NOW(), INTERVAL retention_days DAY);
    SET deleted_reports = ROW_COUNT();

    -- Delete old alert history
    DELETE FROM alert_history 
    WHERE sent_at < DATE_SUB(NOW(), INTERVAL retention_days DAY);
    SET deleted_alerts = ROW_COUNT();

    -- Return summary
    SELECT 
        deleted_reports as deleted_health_reports,
        deleted_alerts as deleted_alert_history,
        retention_days as retention_period_days,
        NOW() as cleanup_completed_at;
END;

